WITH flattened AS (SELECT c.id, c.customer_id, item.product_id, item.qty, item.price, item.promo FROM carts c LATERAL VIEW OUTER EXPLODE(c.items) li AS item), with_dims AS (SELECT e.customer_id, e.product_id, e.qty, p.email FROM flattened e LEFT JOIN customers p ON e.customer_id = p.id), scored AS (SELECT product_id, qty, DENSE_RANK() OVER (PARTITION BY customer_id ORDER BY product_id DESC) AS product_id_dense_rank, DENSE_RANK() OVER (PARTITION BY customer_id ORDER BY qty ASC NULLS FIRST) AS qty_dense_rank FROM with_dims), enriched AS (SELECT *, PERCENT_RANK() OVER (ORDER BY qty_dense_rank ASC NULLS FIRST) AS qty_dense_rank_percent_rank, CUME_DIST() OVER (ORDER BY qty_dense_rank DESC NULLS FIRST) AS qty_dense_rank_cume_dist, DENSE_RANK() OVER (ORDER BY product_id DESC NULLS LAST) AS product_id_dense_rank_2, RANK() OVER w_recent AS product_id_rank FROM scored WINDOW w_recent AS (ORDER BY product_id ASC NULLS LAST)) SELECT product_id, COUNT(*) AS event_count, ROUND(AVG(product_id_dense_rank), 2) AS avg_product_id_dense_rank, PERCENTILE_APPROX(qty_dense_rank_percent_rank, ARRAY(0.25, 0.5, 0.75)) AS qty_dense_rank_percent_rank_quartiles, PERCENTILE_APPROX(qty_dense_rank_cume_dist, 0.9) AS qty_dense_rank_cume_dist_p90 FROM enriched GROUP BY ROLLUP (product_id);
